b=Path('"'"'/home/dombarker/project-offloads/codex-cx-native-prepare2-20261027'"'"');x=json.loads("{\"cfg\": {\"attempt\": \"NBL_L010\", \"kind\": \"lean\", \"module\": \"NBL_PrepareResults\", \"sources\": [\"NBL_generated/NBL_PrepareResults.lean\"], \"command\": [\"/home/dombarker/.elan/toolchains/leanprover--lean4---v4.32.0/bin/lake\", \"env\", \"lean\", \"-j1\", \"-M7000\", \"-DElab.async=false\", \"-R\", \"NBL_generated\", \"-o\", \"/home/dombarker/project-offloads/codex-cx-leaf-cache-20261027/NBL_PrepareResults.olean\", \"NBL_generated/NBL_PrepareResults.lean\"], \"timeout\": 180, \"source_revision\": \"83fbe2521ac0a0412e239358faae6e47b10b8bdd\", \"source_tree_dirty\": true, \"env\": {\"LEAN_PATH\": \"/home/dombarker/project-offloads/codex-cx-leaf-cache-20261027:/home/dombarker/project-offloads/codex-cx-assoc-a2-cache-20261027/XRw_objects:/home/dombarker/project-offloads/codex-cx-sound-int2-20261025:/home/dombarker/project-offloads/codex-cx-sound-int2-20261025/objects:/home/dombarker/.elan/toolchains/leanprover--lean4---v4.32.0/lib/lean\"}, \"deps_fingerprint\": {\"scope\": \"Private prefix modules; XRy persistent cache and coherent SInt2; Aeneas objects pinned in NBL_LIBRARY_PIN.json\"}, \"expected_time\": \"single module symbolic elaboration\", \"reservation_retries\": 0}, \"source\": \"import NBL_PrepareControl\\nset_option autoImplicit false\\nnoncomputable section\\nnamespace AspisR1.NBL_PrepareResults\\nopen Aeneas Aeneas.Std Result AspisR1PublicPreparation NBL_PrepareControl\\nopen PreparedScratchReachability\\n\\n/-- Query rejection exits before rho/powers/claim and preserves old scratch. -/\\ntheorem query_error (B : PreparedScratchModel.Boundaries) {H : Type} (D : aspis_core.Digest32 H)\\n    (sem : r1_semantic.Verified H) (v : verifier.View) (old : Scratch) (o : Opening H)\\n    (e : verifier.Error) (after : transcript.Transcript H)\\n    (call : B.sampling.queries D o.transcript o.row v.final_message=ok (.Err e,after)) :\\n    continuation B D sem v