b=Path('"'"'/home/dombarker/project-offloads/codex-cx-native-prepare2-20261027'"'"');x=json.loads("{\"cfg\": {\"attempt\": \"NBL_L019\", \"kind\": \"lean\", \"module\": \"NBL_OpeningTrace\", \"sources\": [\"NBL_generated/NBL_OpeningTrace.lean\"], \"command\": [\"/home/dombarker/.elan/toolchains/leanprover--lean4---v4.32.0/bin/lake\", \"env\", \"lean\", \"-j1\", \"-M7000\", \"-DElab.async=false\", \"-R\", \"NBL_generated\", \"-o\", \"/home/dombarker/project-offloads/codex-cx-leaf-cache-20261027/NBL_OpeningTrace.olean\", \"NBL_generated/NBL_OpeningTrace.lean\"], \"timeout\": 180, \"source_revision\": \"42c5ae0a52d4dcf07a1463dc9d156406e4b45513\", \"source_tree_dirty\": true, \"env\": {\"LEAN_PATH\": \"/home/dombarker/project-offloads/codex-cx-leaf-cache-20261027:/home/dombarker/project-offloads/codex-cx-assoc-a2-cache-20261027/XRw_objects:/home/dombarker/project-offloads/codex-cx-sound-int2-20261025:/home/dombarker/project-offloads/codex-cx-sound-int2-20261025/objects:/home/dombarker/.elan/toolchains/leanprover--lean4---v4.32.0/lib/lean\"}, \"deps_fingerprint\": {\"scope\": \"Private prefix modules; XRy persistent cache and coherent SInt2; Aeneas objects pinned in NBL_LIBRARY_PIN.json\"}, \"expected_time\": \"single module symbolic elaboration\", \"reservation_retries\": 0}, \"source\": \"import NBL_BlockTrace\\nimport NBL_PrepareControl\\nset_option autoImplicit false\\nnoncomputable section\\nnamespace AspisR1.NBL_OpeningTrace\\nopen Aeneas Aeneas.Std Result AspisR1PublicPreparation NBL_PrepareControl NBL_BlockTrace\\n\\n/-- One source-order S2 opening. Every succeeding call consumes the actual\\npreceding returned carrier, including root||round1 and serialized inactive.\\nThere is no complete opening/prepare output equation in this record. -/\\nstructure Trace {H : Type} (D : aspis_core.Digest32 H)\\n    (sem : r1_semantic.Verified H) (v : verifier.View) (hash : H) where\\n  variant : v.variant=.S2\\n  seed : Bytes32\\n  seedCall : D.digest hash (NBA_Transcript.seed